#include "domain/day_night.hpp"
#include "domain/world_environment.hpp"
#include "domain/needs.hpp"
#include <iostream>
using namespace stalthos;
void check(bool c,const char*m){if(!c)throw std::runtime_error(m);}
int main(){try{auto morning=environment::dayNight(.28,0),day=environment::dayNight(.5,0),evening=environment::dayNight(.72,0),night=environment::dayNight(0,0),repeat=environment::dayNight(1,0);check(morning.sunDirection.x>0&&evening.sunDirection.x<0&&day.sunDirection.y>.999,"sun trajectory");check(day.sunScale>.99&&night.sunScale==0&&night.nightFill>0&&night.ambient.x>0,"day/night readable floor");check(morning.sunColor.y<day.sunColor.y&&evening.sunColor.z<day.sunColor.z,"warm low sun");check(std::abs(night.sunDirection.y-repeat.sunDirection.y)<1e-12,"midnight wrap");for(int i=0;i<=100;++i){auto l=environment::dayNight(i/100.,.6);auto d=l.sunDirection;check(std::abs(d.x*d.x+d.y*d.y+d.z*d.z-1)<1e-12,"unit direction");check(l.skyExposure>=0&&l.sunScale>=0,"bounded light");}
 SimCore clock;clock.advance(2,3);const auto beforePhysical=clock.physicalSeconds(),beforeCalendar=clock.calendarSeconds();needs::NeedsCore n(HeroSpecies::Smalltrotter);n.restoreState(.2,.3,.8,0,true);auto conditions=environment::sample(42,1001,clock.calendarSeconds(),{});for(double phase:{.28,.5,.72,0.})environment::dayNight(phase,conditions.cloud);check(clock.physicalSeconds()==beforePhysical&&clock.calendarSeconds()==beforeCalendar&&n.fatigue()==.8&&n.thirst()==.3,"render preview cannot mutate clock or needs");clock.advance(1,86400);auto next=environment::sample(42,1001,clock.calendarSeconds(),{});check(std::abs(next.dayFraction-conditions.dayFraction)<1e-12&&clock.physicalSeconds()==3,"calendar period without physical acceleration");check(environment::dayNight(.5,1).sunScale<day.sunScale,"cloud dimming retained");bool rejected=false;try{environment::dayNight(-.1,0);}catch(const std::invalid_argument&){rejected=true;}check(rejected,"invalid phase rejected");std::cout<<"DAY_NIGHT_OK trajectory warmth readable night cloud clock separation\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
